#pragma once
#include <string>
inline std::string get_chores_page() {
return R"CHOREPAGE(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Household chores · piTrove</title>
<style>
:root{color-scheme:dark;--bg:#090e19;--card:#121d2d;--line:#29374c;--ink:#eef5ff;--muted:#a3b5cc;--accent:#57c7ee}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#183047,transparent 65%),var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:28px 22px 60px}header{display:flex;justify-content:space-between;align-items:center;gap:16px}h1{font-size:28px;letter-spacing:-.7px;margin:10px 0}h2{font-size:19px;margin:0 0 18px}p{color:var(--muted);margin:8px 0 20px}a{color:var(--accent);text-decoration:none}nav{display:flex;gap:20px;margin:10px 0 25px}.layout{display:grid;grid-template-columns:290px minmax(0,1fr);gap:22px;align-items:start}.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:22px;margin-bottom:20px;box-shadow:0 12px 35px #0002}label{display:block;font-size:13px;font-weight:650;color:var(--muted);margin-bottom:6px}input,select,button{font:inherit}input:not([type=checkbox]):not([type=color]),select{width:100%;border:1px solid var(--line);border-radius:9px;background:var(--bg);color:var(--ink);padding:10px 12px;min-height:43px}input[type=color]{width:42px;height:42px;padding:2px;background:none;border:1px solid var(--line);border-radius:8px}input[type=checkbox]{accent-color:var(--accent);width:20px;height:20px;flex-shrink:0}input:focus,select:focus,button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.field{margin-bottom:15px}.row{display:flex;gap:12px;align-items:center}.row>.grow{flex:1;min-width:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}button,.button{border:1px solid var(--line);border-radius:9px;padding:9px 13px;background:transparent;color:var(--ink);cursor:pointer;display:inline-block}button:hover,.button:hover{border-color:var(--accent)}button.primary{background:var(--accent);border-color:var(--accent);color:#072334;font-weight:750}button:disabled{opacity:.5;cursor:default}.danger{color:#ffb4b4}small,.hint{font-size:12px;color:var(--muted)}.check-label{display:flex;align-items:center;gap:8px;margin:0;color:var(--ink);font-size:14px}.person{padding:13px 0;border-top:1px solid var(--line)}.person-name{font-weight:700;overflow-wrap:anywhere}.person-actions{display:flex;gap:8px;margin-top:8px}.person-actions button,.task-actions button{font-size:12px;padding:5px 9px}.dot{width:10px;height:10px;border-radius:50%;display:inline-block;flex-shrink:0}.task{display:flex;gap:12px;padding:17px 0;border-top:1px solid var(--line);align-items:flex-start}.task-title{font-size:16px;font-weight:700;overflow-wrap:anywhere}.task.done .task-title{text-decoration:line-through;color:var(--muted)}.task-meta{font-size:13px;color:var(--muted);margin-top:5px;overflow-wrap:anywhere}.task-actions{display:flex;gap:7px;margin-top:9px}.badge{font-size:11px;color:#ffc98b;border:1px solid #886742;border-radius:6px;padding:2px 6px;margin-left:8px}.filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}.filters select{width:auto;flex:1;min-width:130px}.notice{border:1px solid #754747;background:#39232b;color:#ffe2e2;padding:12px 16px;border-radius:12px;margin-bottom:16px;white-space:pre-wrap}.status{color:var(--accent);font-size:13px;min-height:24px}.panel-settings{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}.panel-settings h2{margin-bottom:3px}.empty{padding:20px 0;color:var(--muted)}[hidden]{display:none!important}@media(max-width:780px){main{padding:18px 14px 45px}.layout{grid-template-columns:1fr}.grid{grid-template-columns:1fr}header{align-items:flex-start}h1{font-size:24px}.card{padding:18px}.layout>aside{order:1}.task-title{font-size:15px}.filters select{min-width:110px}}
</style></head><body><main>
<header><div><a href="/">piTrove</a><h1>A little teamwork, every day.</h1></div><a class="button" href="/">Controller</a></header>
<nav aria-label="Controller pages"><a href="/">Remote</a><a href="/chores" aria-current="page">People &amp; chores</a></nav>
<p>Add your household, assign a chore, and give it a day or a time. Check it off here when it's done.</p>
<div id="error" class="notice" role="alert" hidden></div><div id="status" class="status" aria-live="polite">Loading your household…</div>
<form id="unlock" class="card" hidden><h2>Unlock household chores</h2><label for="api-key">Controller API key</label><div class="row"><input id="api-key" class="grow" type="password" autocomplete="current-password" required><button class="primary">Unlock</button></div></form>
<section class="card panel-settings" aria-label="Display settings"><div><h2>Chores on your frame</h2><small>Equal side panels keep photos and videos centered, above the news ticker.</small></div><label class="check-label"><input id="panel" type="checkbox" disabled>Show left panel</label></section>
<div class="layout"><aside>
<section class="card"><h2 id="person-heading">Your people</h2><form id="person-form"><input id="person-id" type="hidden"><div class="field"><label for="person-name">Name</label><input id="person-name" maxlength="80" autocomplete="off" placeholder="e.g. Alex" required></div><div class="row"><label for="person-color">Color</label><input id="person-color" type="color" value="#38bdf8"><button id="person-submit" class="primary" type="submit">Add person</button></div><button id="person-cancel" type="button" hidden style="margin-top:12px">Cancel edit</button></form><div id="people"></div></section>
<section class="card"><h2>How it works</h2><p class="hint">Daily chores start fresh each local day. A chore for one date stays overdue until it's done. All-day chores have no deadline; timed chores show their due time.</p><div id="zone" class="hint"></div></section>
</aside><div>
<section class="card"><h2 id="chore-heading">Add a chore</h2><form id="chore-form"><input id="chore-id" type="hidden"><div class="grid"><div class="field"><label for="chore-title">What needs doing?</label><input id="chore-title" maxlength="160" placeholder="e.g. Feed the cat" required></div><div class="field"><label for="chore-person">Who's responsible?</label><select id="chore-person" required><option value="">Add a person first</option></select></div></div><div class="grid"><div class="field"><label for="chore-repeat">When?</label><select id="chore-repeat"><option value="daily">Every day</option><option value="once">On a specific date</option></select></div><div id="date-field" class="field" hidden><label for="chore-date">Date</label><input id="chore-date" type="date"></div></div><div class="row field"><label class="check-label"><input id="all-day" type="checkbox" checked>All day</label><div id="time-field" class="grow" hidden><label for="chore-time">Due at</label><input id="chore-time" type="time"></div></div><div class="row"><button id="chore-submit" class="primary" type="submit" disabled>Add chore</button><button id="chore-cancel" type="button" hidden>Cancel edit</button></div><p id="assign-hint" class="hint">Add someone to your household to get started.</p></form></section>
<section class="card"><div class="row" style="justify-content:space-between"><h2>The chore board</h2><small id="counts"></small></div><div class="filters"><label for="view" class="hint">View</label><select id="view"><option value="today">Today &amp; overdue</option><option value="upcoming">Upcoming</option><option value="all">All chores</option></select><label for="person-filter" class="hint">Person</label><select id="person-filter"><option value="">Everyone</option></select></div><div id="tasks"></div></section>
</div></div></main>
<script>
'use strict';
const $=id=>document.getElementById(id);
let state={people:[],chores:[],today:''}, readSequence=0;
function notice(message){$('error').textContent=message||'';$('error').hidden=!message;}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
async function api(path,fields){const headers={};const key=localStorage.getItem('api_key');if(key)headers.Authorization='Bearer '+key;const opts={headers,cache:'no-store'};if(fields){opts.method='POST';opts.body=new URLSearchParams(fields);headers['Content-Type']='application/x-www-form-urlencoded';}const response=await fetch(path,opts);if(response.status===401){$('unlock').hidden=false;throw Error('Enter your controller API key to manage chores.');}const text=await response.text();let data;try{data=JSON.parse(text);}catch{throw Error(text||'Could not read the controller response.');}if(!response.ok)throw Error(data.error||data.message||'The change could not be saved.');$('unlock').hidden=true;return data;}
function button(label,action,danger=false){const b=el('button',label,danger?'danger':'');b.type='button';b.addEventListener('click',action);return b;}
function scheduleFields(){$('date-field').hidden=$('chore-repeat').value!=='once';$('chore-date').required=!$('date-field').hidden;$('time-field').hidden=$('all-day').checked;$('chore-time').required=!$('all-day').checked;}
function resetPerson(){$('person-form').reset();$('person-id').value='';$('person-heading').textContent='Your people';$('person-submit').textContent='Add person';$('person-cancel').hidden=true;}
function resetChore(){$('chore-form').reset();$('chore-id').value='';$('chore-date').value=state.today;$('chore-heading').textContent='Add a chore';$('chore-submit').textContent='Add chore';$('chore-cancel').hidden=true;scheduleFields();}
function editPerson(p){$('person-id').value=p.id;$('person-name').value=p.name;$('person-color').value=p.color;$('person-heading').textContent='Edit person';$('person-submit').textContent='Save person';$('person-cancel').hidden=false;$('person-name').focus();}
function editChore(c){$('chore-id').value=c.id;$('chore-title').value=c.title;$('chore-person').value=c.person_id;$('chore-repeat').value=c.repeat;$('chore-date').value=c.date||state.today;$('all-day').checked=c.all_day;$('chore-time').value=c.time;$('chore-heading').textContent='Edit chore';$('chore-submit').textContent='Save chore';$('chore-cancel').hidden=false;scheduleFields();$('chore-title').focus();}
async function change(path,fields){try{notice('');await api(path,fields);await load();$('status').textContent='Saved to your frame.';return true;}catch(e){await load();notice(e.message);return false;}}
function render(){
 const people=$('people');people.replaceChildren();const selected=$('chore-person').value,filter=$('person-filter').value;
 $('chore-person').replaceChildren(el('option',state.people.length?'Choose a person':'Add a person first'));$('chore-person').firstChild.value='';$('person-filter').replaceChildren(el('option','Everyone'));$('person-filter').firstChild.value='';
 for(const p of state.people){const option=el('option',p.name);option.value=p.id;$('chore-person').append(option);const f=option.cloneNode(true);$('person-filter').append(f);const row=el('div',undefined,'person'),name=el('div',undefined,'row'),dot=el('span',undefined,'dot');dot.style.backgroundColor=p.color;name.append(dot,el('span',p.name,'person-name'));row.append(name);const assigned=state.chores.filter(c=>c.person_id===p.id).length;row.append(el('small',assigned+' assigned chore'+(assigned===1?'':'s')));const actions=el('div',undefined,'person-actions');actions.append(button('Edit',()=>editPerson(p)));const remove=button('Remove',async()=>{if(confirm('Remove '+p.name+' from your household?')){if(await change('/api/chores/people/delete',{id:p.id}))resetPerson();}},true);remove.disabled=assigned>0;remove.title=assigned?'Reassign or delete their chores first':'Remove person';actions.append(remove);row.append(actions);people.append(row);}
 if(selected)$('chore-person').value=selected;else if(state.people.length===1)$('chore-person').value=state.people[0].id;if(filter)$('person-filter').value=filter;
 $('chore-submit').disabled=!state.people.length;$('assign-hint').hidden=!!state.people.length;
 $('zone').textContent='Household time: '+state.timezone+' · '+state.today;
 renderTasks();
}
function renderTasks(){const person=$('person-filter').value,view=$('view').value;const rows=state.chores.filter(c=>(!person||String(c.person_id)===person)&&(view==='all'||(view==='today'?c.due:!c.due))).sort((a,b)=>Number(a.completed)-Number(b.completed)||(a.date||state.today).localeCompare(b.date||state.today)||a.time.localeCompare(b.time)||a.id-b.id);const tasks=$('tasks');tasks.replaceChildren();const due=state.chores.filter(c=>c.due);$('counts').textContent=due.filter(c=>c.completed).length+' / '+due.length+' done today';
 if(!rows.length)tasks.append(el('div',state.chores.length?'Nothing in this view. Enjoy the breathing room.':'Your first chore starts here. Add one above.','empty'));
 for(const c of rows){const p=state.people.find(p=>p.id===c.person_id),row=el('div',undefined,'task'+(c.completed?' done':''));const check=el('input');check.type='checkbox';check.checked=c.completed;check.setAttribute('aria-label',(c.completed?'Mark incomplete: ':'Complete: ')+c.title);check.addEventListener('change',async()=>{check.disabled=true;const ok=await change('/api/chores/tasks/complete',{id:c.id,date:c.repeat==='daily'?state.today:c.date,completed:check.checked?'1':'0'});if(!ok){check.checked=c.completed;check.disabled=false;}});const content=el('div',undefined,'grow');content.style.minWidth='0';const title=el('div',c.title,'task-title');if(!c.completed&&c.repeat==='once'&&c.date<state.today)title.append(el('span','Overdue','badge'));content.append(title);const meta=el('div',undefined,'task-meta'),dot=el('span',undefined,'dot');dot.style.backgroundColor=p?p.color:'#38bdf8';meta.append(dot,document.createTextNode(' '+(p?p.name:'Unknown person')+' · '+(c.repeat==='daily'?'Every day':c.date)+' · '+(c.all_day?'All day':c.time)));content.append(meta);const actions=el('div',undefined,'task-actions');actions.append(button('Edit',()=>editChore(c)),button('Delete',async()=>{if(confirm('Delete “'+c.title+'”?')){if(await change('/api/chores/tasks/delete',{id:c.id}))if($('chore-id').value===String(c.id))resetChore();}},true));content.append(actions);row.append(check,content);tasks.append(row);}
}
async function load(){const sequence=++readSequence;try{const data=await api('/api/chores');if(sequence!==readSequence)return;state=data;render();if(!$('chore-date').value)$('chore-date').value=state.today;$('status').textContent='Chores follow your frame’s local time.';}catch(e){notice(e.message);$('status').textContent='';}}
$('chore-repeat').addEventListener('change',scheduleFields);$('all-day').addEventListener('change',scheduleFields);$('person-cancel').addEventListener('click',resetPerson);$('chore-cancel').addEventListener('click',resetChore);$('view').addEventListener('change',renderTasks);$('person-filter').addEventListener('change',renderTasks);
$('person-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('person-submit');b.disabled=true;if(await change('/api/chores/people/save',{id:$('person-id').value,name:$('person-name').value.trim(),color:$('person-color').value}))resetPerson();b.disabled=false;});
$('chore-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('chore-submit');b.disabled=true;if(await change('/api/chores/tasks/save',{id:$('chore-id').value,person_id:$('chore-person').value,title:$('chore-title').value.trim(),repeat:$('chore-repeat').value,date:$('chore-date').value,all_day:$('all-day').checked?'1':'0',time:$('chore-time').value}))resetChore();b.disabled=!state.people.length;});
$('unlock').addEventListener('submit',async e=>{e.preventDefault();localStorage.setItem('api_key',$('api-key').value);$('api-key').value='';notice('');await load();await panelSettings();});
async function panelSettings(){try{const settings=await api('/api/settings');$('panel').checked=!!settings.left_panel_enabled&&!!settings.infopanels_enabled;$('panel').disabled=false;}catch(e){notice(e.message);}}
$('panel').addEventListener('change',async()=>{const control=$('panel');control.disabled=true;try{notice('');const key=localStorage.getItem('api_key'),headers={};if(key)headers.Authorization='Bearer '+key;const response=await fetch('/api/settings/update?left_panel_enabled='+(control.checked?'1&infopanels_enabled=1':'0'),{headers});if(!response.ok)throw Error('Could not save the panel setting.');$('status').textContent=control.checked?'Left panel enabled on your frame.':'Left panel hidden. Your chores are saved.';}catch(e){control.checked=!control.checked;notice(e.message);}finally{control.disabled=false;}});
scheduleFields();load();panelSettings();setInterval(()=>{if(!document.hidden)load();},30000);
</script></body></html>)CHOREPAGE";
}
